<?php require __DIR__.'/app/bootstrap.php';Auth::requireLogin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,t.title FROM ai_outputs a JOIN transcripts t ON t.id=a.transcript_id WHERE a.id=? AND a.user_id=?');$s->execute([$id,Auth::id()]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Output not found');}$pageTitle='AI output';require __DIR__.'/app/views/header.php';?><main class="app-shell"><div class="container"><a href="<?=e(url('transcript.php?id='.$o['transcript_id']))?>">← Back to transcript</a><section class="panel-card mt-3"><div class="d-flex justify-content-between"><div><h1 class="h3 fw-bold"><?=e(ucfirst($o['task']))?></h1><p class="text-secondary"><?=e($o['title']?:'Transcript')?></p></div><button class="btn btn-outline-secondary btn-sm" data-copy="#output">Copy</button></div><div id="output" class="transcript-body mt-4"><?=e($o['output_text'])?></div></section></div></main><?php require __DIR__.'/app/views/footer.php';?>
